<?php
use Illuminate\Support\Facades\Route;use App\Http\Controllers\Api\{AccountController,OrganizationController,CurrencyController,DebtTypeController,DebtController,PaymentController,DashboardController,ReportController};
Route::middleware(['auth:sanctum'])->group(function(){Route::get('dashboard',DashboardController::class);Route::apiResource('organizations',OrganizationController::class);Route::apiResource('currencies',CurrencyController::class);Route::apiResource('debt-types',DebtTypeController::class);Route::apiResource('accounts',AccountController::class);Route::get('accounts/{account}/statement',[AccountController::class,'statement']);Route::apiResource('debts',DebtController::class);Route::apiResource('payments',PaymentController::class);Route::post('payments/{payment}/reverse',[PaymentController::class,'reverse']);Route::prefix('reports')->group(function(){Route::get('debts',[ReportController::class,'debts']);Route::get('payments',[ReportController::class,'payments']);Route::get('overdue',[ReportController::class,'overdue']);Route::get('export',[ReportController::class,'export']);});});
